// Capture the hand-authored Romanian HTML once so every switch is reversible.
document.querySelectorAll('[data-i18n],[data-i18n-html]').forEach(el=>{const key=el.dataset.i18n||el.dataset.i18nHtml;translations.ro[key]=el.dataset.i18nHtml?el.innerHTML:el.textContent;});
document.querySelectorAll('[data-alt]').forEach(el=>translations.ro[el.dataset.alt]=el.alt);
Object.assign(translations.ro,{pause:'Pauză',resume:'Continuă',reviewLink:'Citește pe Google Maps',storyPhotoNote:'O brutărie mică.<br>O pasiune mare.'});
const reviews=[{lang:'ro',text:'O brutărie pe care o vizitez regulat, practic consum pâine doar de la ei. Mulțumesc pentru munca depusă 🙏',url:'https://maps.app.goo.gl/Tkoa8Gzg5NysVMKq6'},{lang:'en',text:'THE BREAD in town. It’s a family business and baking bread it’s passion then became a business. Very very good bread, but not only bread but all sorts of pastries and cookies. Just try :)',url:'https://maps.app.goo.gl/VYNt8BefRypbdZLy6'},{lang:'en',text:"As always, everything is delicious! It's best to come here after lunch, because you'll want to try literally everything 😄",url:'https://maps.app.goo.gl/Tkoa8Gzg5NysVMKq6'},{lang:'ro',text:'Am luat două pâini.\nCând am ajuns acasă, una am mâncat-o instant.\nPâinea exact cum îmi place mie.\nBaftă în continuare, să creșteți la mai mult și la mai mare.',url:'https://maps.app.goo.gl/immdB9AZjztaV4tS8'},{lang:'en',text:"A wonderful, small, and very cozy family-run bakery, where the baker's mistress greets you behind the counter and will delightfully tell you about the bread, pastries, and cookies.\nMy favorite is Gilti Pleasure with my morning coffee 🤍.",url:'https://maps.app.goo.gl/L2bdGoTmtbwhmSmD8'}];
const track=document.querySelector('#review-track'),windowEl=document.querySelector('.review-window'),pauseButton=document.querySelector('#review-pause');
const star='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2 3 6.1 6.7 1-4.9 4.7 1.2 6.7-6-3.2-6 3.2 1.2-6.7-4.9-4.7 6.7-1Z"/></svg>';
document.querySelectorAll('span[aria-hidden="true"]').forEach(el=>{if(el.textContent==='↗')el.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';});
reviews.forEach(r=>{const card=document.createElement('article');card.className='review-card';const stars=document.createElement('div');stars.className='stars';stars.setAttribute('role','img');stars.setAttribute('aria-label','5 / 5');stars.innerHTML=star.repeat(5);const quote=document.createElement('blockquote');quote.lang=r.lang;quote.textContent=r.text;const link=document.createElement('a');link.href=r.url;link.target='_blank';link.rel='noopener noreferrer';link.dataset.reviewLink='';card.append(stars,quote,link);track.append(card);});
let locale='ro',paused=false,hovered=false,focused=false,inView=true,tween;
const motionQuery=matchMedia('(prefers-reduced-motion: reduce)');
function translate(lang){locale=Object.hasOwn(translations,lang)?lang:'ro';const dict=translations[locale];document.documentElement.lang=locale;document.querySelectorAll('[data-i18n]').forEach(el=>{if(dict[el.dataset.i18n])el.textContent=dict[el.dataset.i18n];});document.querySelectorAll('[data-i18n-html]').forEach(el=>{if(dict[el.dataset.i18nHtml])el.innerHTML=dict[el.dataset.i18nHtml];});document.querySelectorAll('[data-alt]').forEach(el=>{el.alt=dict[el.dataset.alt]||translations.ro[el.dataset.alt];});document.querySelector('.photo-note').innerHTML=dict.storyPhotoNote;document.querySelectorAll('[data-review-link]').forEach(el=>el.textContent=dict.reviewLink);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===locale)));document.title={ro:'Miez — Brutărie Artizanală în Chișinău',ru:'Miez — Ремесленная пекарня в Кишинёве',en:'Miez — Artisan Bakery in Chișinău'}[locale];document.querySelector('.navigation').setAttribute('aria-label',{ro:'Navigare principală',ru:'Основная навигация',en:'Main navigation'}[locale]);windowEl.setAttribute('aria-label',{ro:'Recenzii Google Maps',ru:'Отзывы Google Maps',en:'Google Maps reviews'}[locale]);updateMotion();}
function updateMotion(){pauseButton.textContent=translations[locale][paused?'resume':'pause'];pauseButton.setAttribute('aria-pressed',String(paused));if(tween)tween.paused(paused||hovered||focused||document.hidden||!inView||motionQuery.matches);}
function setupMotion(){if(tween){tween.kill();tween=null;}track.querySelectorAll('[data-duplicate]').forEach(el=>el.remove());gsap.set(track,{x:0});if(motionQuery.matches)return;const originals=[...track.children];originals.forEach(card=>{const clone=card.cloneNode(true);clone.dataset.duplicate='';clone.setAttribute('aria-hidden','true');clone.querySelectorAll('a').forEach(a=>a.tabIndex=-1);track.append(clone);});const distance=track.children[5].offsetLeft-track.children[0].offsetLeft;tween=gsap.to(track,{x:-distance,duration:distance/24,ease:'none',repeat:-1});updateMotion();}
pauseButton.addEventListener('click',()=>{paused=!paused;updateMotion();});windowEl.addEventListener('mouseenter',()=>{hovered=true;updateMotion();});windowEl.addEventListener('mouseleave',()=>{hovered=false;updateMotion();});windowEl.addEventListener('focusin',()=>{focused=true;updateMotion();});windowEl.addEventListener('focusout',e=>{if(!windowEl.contains(e.relatedTarget)){focused=false;updateMotion();}});document.addEventListener('visibilitychange',updateMotion);
// Language preference is also reflected in the URL for shareable language selection.
document.querySelectorAll('[data-lang]').forEach(button=>button.addEventListener('click',()=>{const url=new URL(location.href);url.searchParams.set('lang',button.dataset.lang);history.replaceState(null,'',url);translate(button.dataset.lang);try{localStorage.setItem('miez-language',locale);}catch{}}));
let stored;try{stored=localStorage.getItem('miez-language');}catch{}translate(new URL(location.href).searchParams.get('lang')||stored||'ro');
windowEl.addEventListener('pointerdown',()=>{paused=true;updateMotion();});
windowEl.addEventListener('focusin',()=>{if(tween)tween.progress(0).pause();});
document.querySelector('#year').textContent=new Date().getFullYear();
if(window.gsap){setupMotion();let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(setupMotion,200);});motionQuery.addEventListener('change',setupMotion);new IntersectionObserver(entries=>{inView=entries[0].isIntersecting;updateMotion();}).observe(windowEl);if(!motionQuery.matches)gsap.from('.hero-copy > *',{y:15,opacity:.65,duration:.75,stagger:.08,ease:'power3.out',clearProps:'all'});}
